// Ноды Postgres отдают результат запроса, а не событие.
// Возвращаем исходное событие, чтобы сценарий работал с ним.
return [{ json: $('Событие от источника').first().json }];

// ══════════════════════════════════════════════════════════════════════════
// ЕДИНСТВЕННОЕ место, где описано поведение бота: экраны, кнопки, форма заказа.
// Правится прямо в редакторе n8n, Save — и всё. Рестарт контейнера не нужен.
//
// Вход:  $('Вернуть событие') — событие,  $json — строка dialog_state.
// Выход: { action, reply, state, order }
//   action: 'reply' — просто ответить | 'order' — оформить заказ | 'rates' — сходить за курсом
//   state:  новое состояние диалога или null, чтобы очистить
// ══════════════════════════════════════════════════════════════════════════

const COMPANY = {
  name: 'Тест Компания',
  site: 'https://dev.max.ru/docs',
  phone: '+78442000000',
  phoneHuman: '+7 (8442) 00-00-00',
  address: 'г. Волгоград, ул. Тестовая, 1',
  lat: 48.707067,
  lon: 44.516974,
};

// Каталог: ключ -> товар. Добавить позицию = добавить ключ, кнопки соберутся сами.
const CATALOG = {
  a: {
    title: 'Кофемашина «Утро»',
    price: 24900,
    short: 'зерновая, 15 бар',
    desc: 'Зерновая кофемашина с автоматическим капучинатором.\n\n'
        + '• давление 15 бар\n• бункер 250 г зерна\n• резервуар 1.8 л\n'
        + '• автоочистка от накипи\n\nГарантия 2 года.',
  },
  b: {
    title: 'Чайник «Пар»',
    price: 3400,
    short: '1.7 л, нержавейка',
    desc: 'Электрочайник из нержавеющей стали.\n\n'
        + '• объём 1.7 л\n• мощность 2200 Вт\n• закипает за 4 минуты\n'
        + '• защита от включения без воды\n\nГарантия 1 год.',
  },
  c: {
    title: 'Термос «Дорога»',
    price: 1890,
    short: '0.75 л, держит 12 ч',
    desc: 'Вакуумный термос для поездок.\n\n'
        + '• объём 0.75 л\n• держит температуру 12 часов\n'
        + '• крышка-кружка\n• не течёт в сумке\n\nГарантия 1 год.',
  },
};

const money = (n) => n.toLocaleString('ru-RU') + ' ₽';
const QTY_PRESETS = [1, 2, 5];
// Сколько живёт незаконченная форма. Дальше её убирает prune_bot_events().
const FORM_TTL_MINUTES = 30;

// ─────────────────────────────────────────── экраны
function screenMain(ev) {
  return {
    text: `Привет, ${ev.name}! 👋\nЯ демо-бот «${COMPANY.name}», собранный целиком в n8n.\n\nВыберите раздел:`,
    buttons: [
      [
        { type: 'callback', text: '🏢 О компании', payload: 'about' },
        { type: 'callback', text: '📋 Каталог', payload: 'catalog' },
      ],
      [
        { type: 'callback', text: '💱 Курс валют', payload: 'rates' },
        { type: 'callback', text: '🧾 Мои заказы', payload: 'myorders' },
      ],
      [{ type: 'request_geo_location', text: '📍 Я рядом?' }],
      [{ type: 'link', text: '🌐 Документация MAX', url: 'https://dev.max.ru/docs' }],
    ],
  };
}

function screenAbout() {
  return {
    // clipboard кладёт телефон в буфер обмена — набирать руками не нужно.
    text: `🏢 *${COMPANY.name}*\n\nЭто тестовая компания: витрина возможностей связки n8n + MAX. `
        + `Товаров на складе нет, заказы никуда не уезжают, кроме нашей базы.\n\n`
        + `📍 ${COMPANY.address}\n📞 ${COMPANY.phoneHuman}`,
    buttons: [
      [{ type: 'link', text: '🌐 Наш сайт', url: COMPANY.site }],
      [{ type: 'clipboard', text: '📋 Скопировать телефон', payload: COMPANY.phone }],
      [{ type: 'callback', text: '⬅️ Назад', payload: 'main' }],
    ],
  };
}

function screenCatalog() {
  const rows = Object.entries(CATALOG).map(([id, p]) => [
    { type: 'callback', text: `${p.title} — ${money(p.price)}`, payload: `item:${id}` },
  ]);
  return {
    text: '📋 *Каталог*\n\nВыберите товар, чтобы прочитать подробности:',
    buttons: [...rows, [{ type: 'callback', text: '⬅️ В меню', payload: 'main' }]],
  };
}

function screenItem(id) {
  const p = CATALOG[id];
  if (!p) return screenCatalog();
  return {
    text: `*${p.title}*\n_${p.short}_\n\n${p.desc}\n\nЦена: *${money(p.price)}*`,
    buttons: [
      [{ type: 'callback', text: '🛒 Заказать', payload: `order:${id}` }],
      [{ type: 'callback', text: '⬅️ В каталог', payload: 'catalog' }],
    ],
  };
}

// ─────────────────────────────────────────── форма заказа
function askQty(id) {
  const p = CATALOG[id];
  return {
    text: `🛒 Заказ: *${p.title}*\nЦена: ${money(p.price)}\n\n`
        + 'Шаг 1 из 2. Сколько штук? Нажмите кнопку или напишите число сообщением.',
    buttons: [
      QTY_PRESETS.map((n) => ({ type: 'callback', text: String(n), payload: `qty:${n}` })),
      [{ type: 'callback', text: '✖️ Отменить', payload: 'cancel' }],
    ],
  };
}

function askPhone(id, qty) {
  const p = CATALOG[id];
  return {
    text: `🛒 *${p.title}* × ${qty}\nИтого: *${money(p.price * qty)}*\n\n`
        + 'Шаг 2 из 2. Как с вами связаться? Отправьте контакт кнопкой '
        + 'или напишите телефон сообщением.',
    buttons: [
      [{ type: 'request_contact', text: '📱 Отправить мой контакт' }],
      [{ type: 'callback', text: '✖️ Отменить', payload: 'cancel' }],
    ],
  };
}

// Телефон из текста: 10-15 цифр, лишнее отбрасываем.
function parsePhone(text) {
  const digits = (text || '').replace(/[^\d+]/g, '');
  return /^\+?\d{10,15}$/.test(digits) ? digits : null;
}

// ─────────────────────────────────────────── сборка ответа
const ev = $('Вернуть событие').first().json;
const st = $json ?? {};
const state = { screen: st.screen ?? 'main', step: st.step ?? null, data: st.data ?? {} };

// Нажатие кнопки отвечаем через /answers — сообщение меняется на месте.
// Обычное сообщение отправляем через /messages.
function envelope(scr) {
  const body = {
    text: scr.text,
    format: 'markdown',
    attachments: [{ type: 'inline_keyboard', payload: { buttons: scr.buttons } }],
  };
  if (ev.kind === 'callback' && ev.callback_id) {
    return { api_path: 'answers', api_query: { callback_id: ev.callback_id }, body: { message: body } };
  }
  return { api_path: 'messages', api_query: { chat_id: String(ev.chat_id) }, body };
}

const out = (scr, opts = {}) => [{
  json: {
    action: opts.action ?? 'reply',
    reply: envelope(scr),
    state: opts.state ?? null,
    order: opts.order ?? null,
    ttl_minutes: FORM_TTL_MINUTES,
  },
}];

const key = ev.kind === 'callback' ? (ev.payload || 'main') : '';
const text = ev.text || '';

// ── 1. Форма заказа перехватывает ввод раньше меню: пока идёт шаг, число или
//       телефон означают ответ на вопрос, а не команду.
if (state.screen === 'order' && key !== 'cancel' && !key.startsWith('item:')
    && key !== 'main' && key !== 'catalog') {
  const pid = state.data.product_id;
  const p = CATALOG[pid];

  if (!p) return out(screenCatalog(), { state: null });   // товар исчез из каталога

  if (state.step === 'qty') {
    const qty = key.startsWith('qty:') ? Number(key.slice(4)) : Number(text.replace(/\s/g, ''));
    if (!Number.isInteger(qty) || qty < 1 || qty > 99) {
      return out({
        text: '🤔 Нужно целое число от 1 до 99.\n\n' + askQty(pid).text,
        buttons: askQty(pid).buttons,
      }, { state: { screen: 'order', step: 'qty', data: state.data } });
    }
    return out(askPhone(pid, qty),
      { state: { screen: 'order', step: 'phone', data: { ...state.data, qty } } });
  }

  if (state.step === 'phone') {
    const phone = ev.contact_phone ?? parsePhone(text);
    if (!phone) {
      return out({
        text: '🤔 Не разобрал номер. Отправьте контакт кнопкой или напишите телефон цифрами.',
        buttons: askPhone(pid, state.data.qty).buttons,
      }, { state: { screen: 'order', step: 'phone', data: state.data } });
    }
    // Заказ собран. Сам ответ соберётся после вставки в БД — нужен его номер.
    return [{
      json: {
        action: 'order',
        reply: null,
        state: null,
        order: {
          product_id: pid,
          product_title: p.title,
          qty: state.data.qty,
          price_rub: p.price,
          total_rub: p.price * state.data.qty,
          phone,
        },
        ttl_minutes: FORM_TTL_MINUTES,
      },
    }];
  }
}

// ── 2. Обычные экраны
if (key === 'cancel') return out({
  text: '✖️ Заказ отменён.',
  buttons: [[{ type: 'callback', text: '⬅️ В меню', payload: 'main' }]],
}, { state: null });

if (key === 'about') return out(screenAbout());
if (key === 'catalog') return out(screenCatalog());
if (key.startsWith('item:')) return out(screenItem(key.slice(5)));

if (key.startsWith('order:')) {
  const id = key.slice(6);
  if (!CATALOG[id]) return out(screenCatalog());
  return out(askQty(id), { state: { screen: 'order', step: 'qty', data: { product_id: id } } });
}

// Курс валют уходит за данными во внешний API — ответ соберётся после запроса.
if (key === 'rates' || /^\/(rates|курс)$/i.test(text)) {
  return [{ json: { action: 'rates', reply: null, state: null, order: null,
                    ttl_minutes: FORM_TTL_MINUTES } }];
}

if (key === 'myorders' || /^\/orders$/i.test(text)) {
  return [{ json: { action: 'myorders', reply: null, state: null, order: null,
                    ttl_minutes: FORM_TTL_MINUTES } }];
}

// ── 3. Текстовые команды и свободный ввод
if (/^\/whoami$/i.test(text)) return out({
  // Свой user_id нужен, чтобы прописать себя в ADMIN_IDS и получать заказы.
  text: `🪪 Ваш user_id: \`${ev.user_id}\`\nchat_id диалога: \`${ev.chat_id}\`\n\n`
      + 'Впишите user_id в ADMIN_IDS в .env, чтобы получать уведомления о заказах.',
  buttons: [[{ type: 'callback', text: '⬅️ В меню', payload: 'main' }]],
});

if (ev.geo) return out({
  text: `📍 Спасибо! Ваши координаты: ${ev.geo.lat.toFixed(4)}, ${ev.geo.lon.toFixed(4)}.\n\n`
      + `Мы находимся по адресу ${COMPANY.address}.`,
  buttons: [[{ type: 'callback', text: '⬅️ В меню', payload: 'main' }]],
});

if (/^эхо\s+/i.test(text)) return out({
  text: '🔁 Вы написали: ' + text.replace(/^эхо\s+/i, ''),
  buttons: [[{ type: 'callback', text: '⬅️ В меню', payload: 'main' }]],
});

// Всё остальное, включая /start и неизвестный payload, — главное меню.
return out(screenMain(ev), { state: null });

// Заказ уже в базе, её номер известен — собираем два сообщения:
// подтверждение пользователю и уведомление админам. Обе уходят одной и той же
// нодой отправки, просто разными items.
const ev = $('Вернуть событие').first().json;
const o = $('Сценарий').first().json.order;
const row = $json;                       // строка из «Создать заказ»
const money = (n) => Number(n).toLocaleString('ru-RU') + ' ₽';

const items = [{
  json: {
    api_path: 'messages',
    api_query: { chat_id: String(ev.chat_id) },
    body: {
      text: `✅ Заказ *№${row.id}* принят!\n\n`
          + `${o.product_title} × ${o.qty}\nИтого: *${money(o.total_rub)}*\n`
          + `Телефон: ${o.phone}\n\nМенеджер свяжется с вами.`,
      format: 'markdown',
      attachments: [{ type: 'inline_keyboard', payload: { buttons: [
        [{ type: 'callback', text: '🧾 Мои заказы', payload: 'myorders' }],
        [{ type: 'callback', text: '⬅️ В меню', payload: 'main' }],
      ] } }],
    },
  },
}];

// ADMIN_IDS — список user_id через запятую. Пусто — уведомлять некого,
// заказ всё равно лежит в базе. Свой id можно узнать командой /whoami.
const admins = String($env.ADMIN_IDS ?? '').split(',').map((s) => s.trim()).filter(Boolean);
for (const id of admins) {
  items.push({
    json: {
      api_path: 'messages',
      api_query: { user_id: String(id) },
      body: {
        text: `🔔 *Новый заказ №${row.id}*\n\n`
            + `${o.product_title} × ${o.qty}\nСумма: ${money(o.total_rub)}\n`
            + `Телефон: ${o.phone}\n`
            + `Клиент: ${ev.name}${ev.username ? ' (@' + ev.username + ')' : ''}, id ${ev.user_id}`,
        format: 'markdown',
      },
    },
  });
}

return items;

// Ответ ЦБ РФ -> экран с курсами. Это и есть главный довод в пользу n8n:
// сходить во внешний API и подмешать данные в ответ — одна нода HTTP Request,
// без единой строки инфраструктурного кода.
const ev = $('Вернуть событие').first().json;
// Нода настроена на responseFormat: json, но если ответ всё же придёт строкой
// (например, ЦБ сменит content-type), разберём его сами — экран не должен пустеть.
const raw = $json ?? {};
const d = raw.Valute ? raw : JSON.parse(raw.data ?? raw.body ?? '{}');
const v = d.Valute ?? {};
const fmt = (c) => (v[c] ? `${v[c].Name}: *${v[c].Value.toFixed(2)} ₽* (${v[c].Previous > v[c].Value ? '↓' : '↑'})` : null);
const lines = ['USD', 'EUR', 'CNY'].map(fmt).filter(Boolean);
const date = (d.Date ?? '').slice(0, 10).split('-').reverse().join('.');

const body = {
  text: `💱 *Курс ЦБ РФ* на ${date}\n\n${lines.join('\n')}`,
  format: 'markdown',
  attachments: [{ type: 'inline_keyboard', payload: { buttons: [
    [{ type: 'callback', text: '🔄 Обновить', payload: 'rates' }],
    [{ type: 'callback', text: '⬅️ В меню', payload: 'main' }],
  ] } }],
};

if (ev.kind === 'callback' && ev.callback_id) {
  return [{ json: { api_path: 'answers', api_query: { callback_id: ev.callback_id }, body: { message: body } } }];
}
return [{ json: { api_path: 'messages', api_query: { chat_id: String(ev.chat_id) }, body } }];

// Список заказов пользователя из базы. Показывает чтение из Postgres в ответ
// на нажатие кнопки.
const ev = $('Вернуть событие').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r.id);
const money = (n) => Number(n).toLocaleString('ru-RU') + ' ₽';

const text = rows.length
  ? '🧾 *Ваши заказы*\n\n' + rows.map((r) =>
      `*№${r.id}* — ${r.product_title} × ${r.qty}\n${money(r.total_rub)} · ${r.status} · `
      + new Date(r.created_at).toLocaleDateString('ru-RU')).join('\n\n')
  : '🧾 Заказов пока нет.\n\nЗагляните в каталог — оформление занимает два шага.';

const body = {
  text,
  format: 'markdown',
  attachments: [{ type: 'inline_keyboard', payload: { buttons: [
    [{ type: 'callback', text: '📋 В каталог', payload: 'catalog' }],
    [{ type: 'callback', text: '⬅️ В меню', payload: 'main' }],
  ] } }],
};

if (ev.kind === 'callback' && ev.callback_id) {
  return [{ json: { api_path: 'answers', api_query: { callback_id: ev.callback_id }, body: { message: body } } }];
}
return [{ json: { api_path: 'messages', api_query: { chat_id: String(ev.chat_id) }, body } }];
